 const top=node('div',undefined,{class:'career-heading'}),head=node('div');head.append(node('span','YOUR NEXT CHAPTER',{class:'career-eyebrow'}),node('h2','Career Studio'),node('p','Build your story. Prepare your next move.'));const topActions=node('div',undefined,{class:'career-actions'});top.append(head,topActions);root.append(top);
 const saveState=node('p','Session only · export your project to keep it',{role:'status',class:'career-save-state'}),nav=node('nav',undefined,{'aria-label':'Career Studio areas',class:'career-nav'}),subnav=node('nav',undefined,{'aria-label':'Career Studio tasks',class:'career-subnav'}),body=node('div',undefined,{class:'career-body'}),status=node('p','Ready',{role:'status','aria-live':'polite',class:'career-status'});root.append(saveState,nav,subnav,body,status);
