 function restoreInPlace(target,source){for(const key of Object.keys(target))if(!Object.hasOwn(source,key))delete target[key];for(const[key,value]of Object.entries(source)){if(Array.isArray(value)&&Array.isArray(target[key])){const previous=target[key];const next=value.map((v,i)=>{const old=v&&typeof v==='object'?(v.id?previous.find(x=>x?.id===v.id):previous[i]):null;if(old&&typeof old==='object'){restoreInPlace(old,v);return old}return clone(v)});previous.splice(0,previous.length,...next)}else if(value&&typeof value==='object'&&target[key]&&typeof target[key]==='object')restoreInPlace(target[key],value);else target[key]=clone(value)}}
 const say=(message,error=false)=>{status.textContent=message;status.dataset.error=String(error)};
 const safe=fn=>async(...args)=>{try{await fn(...args)}catch(e){say(e.message||String(e),true)}};
 function button(parent,label,fn,attrs={}){const b=node('button',label,{type:'button',...attrs});b.onclick=safe(fn);parent.append(b);return b}
 function row(parent){const e=node('div',undefined,{class:'career-actions'});parent.append(e);return e}
 function card(parent,title,intro){const c=node('section',undefined,{class:'career-card'});c.append(node('h3',title));if(intro)c.append(node('p',intro,{class:'career-muted'}));parent.append(c);return c}
 function details(parent,title,open=false){const d=node('details',undefined,{open});d.append(node('summary',title));parent.append(d);return d}
 function field(parent,label,value='',type='text',change,opts){const l=node('label',undefined,{class:'career-field'});l.append(node('span',label));let e;if(type==='select'){e=node('select',undefined,{'aria-label':label});for(const option of opts||[]){const[v,t]=Array.isArray(option)?option:[option,option];e.append(new Option(t,v))}e.value=value}else if(type==='checkbox')e=node('input',undefined,{type,checked:!!value,'aria-label':label});else e=node(type==='textarea'?'textarea':'input',undefined,type==='textarea'?{value,rows:4,'aria-label':label}:{value,type,'aria-label':label});if(type==='text'||type==='textarea')e.maxLength=label==='Job description'?100000:12000;l.append(e);parent.append(l);if(change)e.addEventListener(type==='select'||type==='checkbox'||type==='file'?'change':'input',()=>safe(()=>change(type==='checkbox'?e.checked:type==='number'?Number(e.value):e.value,e))());return e}
 function select(parent,label,value,options,change){return field(parent,label,value,'select',change,options)}
