 function pushHistory(before,key){const now=Date.now();if(lastEdit!==key||now-lastEditAt>900){history.push(before);while(history.length>30||history.reduce((n,x)=>n+x.length,0)>24000000)history.shift()}lastEdit=key;lastEditAt=now;future=[]}
 function changed(fn,key='action'){const before=JSON.stringify(p);try{fn();validateProject(p)}catch(e){restoreInPlace(p,JSON.parse(before));throw e}if(before!==JSON.stringify(p)){pushHistory(before,key);updateSavedState();if(status.dataset.error==='true')say('Changes applied. Review the document before sharing.');clearTimeout(autosaveTimer);if(enabled&&!blocked)autosaveTimer=setTimeout(saveLocal,500)}return p}
 function updateSavedState(){const dirty=JSON.stringify(p)!==savedSignature;saveState.textContent=(dirty?'Unsaved changes':'Session unchanged / project exported')+' · '+(enabled?blocked?'Recovery needs review':'Local recovery enabled':'Session only');}
 function saveLocal(){if(!enabled||blocked||disposed)return;try{const raw=localStorage.getItem(draftKey);if(raw!==lastRaw){blocked=true;updateSavedState();say('Recovery changed in another tab. Review it under Project & recovery before saving.',true);return}const next=JSON.stringify({format:'toolstudio-career-recovery',version:1,at:new Date().toISOString(),data:validateProject(p)});localStorage.setItem(draftKey,next);lastRaw=next;saveState.textContent='Local recovery saved · '+new Date().toLocaleTimeString()+' · export a project for a portable copy'}catch(e){say('Local recovery could not save: '+e.message,true)}}
 function recover(raw){const x=JSON.parse(raw||'null');if(x?.format!=='toolstudio-career-recovery'||x.version!==1)throw Error('Invalid recovery record');return validateProject(x.data)}
 function undo(){if(!history.length)return;future.push(JSON.stringify(p));p=validateProject(JSON.parse(history.pop()));lastEdit='';render();updateSavedState();if(enabled&&!blocked)saveLocal()}
