 function modal(title,build){const dialog=node('dialog',undefined,{class:'career-dialog','aria-label':title}),content=node('div'),actions=row(dialog);dialog.prepend(node('h3',title),content);button(actions,'Close',()=>dialog.close());dialog.addEventListener('close',()=>dialog.remove(),{once:true});root.append(dialog);build(content,actions,dialog);dialog.showModal();return dialog}
 function reviewProject(candidate,label){const next=validateProject(candidate),baseline=JSON.stringify(p);modal('Review '+label,(content,actions,d)=>{note(content,'This replaces the Career Studio project. Your original career tools keep their data. Undo restores this Studio session.');content.append(node('pre',JSON.stringify({name:next.profile.name,resumes:next.resumes.length,applications:next.applications.length,evidence:next.evidence.length,questions:next.questions.length,skills:next.growth.length,retainedOriginal:!!next.legacy},null,2)));button(actions,'Use reviewed project',()=>{if(JSON.stringify(p)!==baseline)throw Error('Current project changed; review again');pushHistory(baseline,'import');p=clone(next);active='master';application='';editId='';d.close();render();updateSavedState();if(enabled&&!blocked)saveLocal();say('Reviewed project loaded. Export it to retain a portable copy.')})})}
 function chooseArea(next,nextTab){area=next;tab=nextTab||tabs[next]?.[0]?.[0]||'';editId='';render()}
