 function manageSelected(){const collection={evidence:'evidence',documents:'documents',offers:'offers',questions:'questions',roadmap:'growth',reviews:'reviews',tracker:'applications'}[tab],id=tab==='tracker'?application:editId;if(!collection||!p[collection].some(r=>r.id===id))return;const tools=details(body,'Manage selected record');button(tools,'Remove selected record',()=>{if(collection==='evidence'&&(p.applications.some(a=>a.requirements.some(r=>r.evidenceId===id))||p.reviews.some(r=>r.evidence.includes(id))))throw Error('Unlink this achievement from requirements and reviews before removing it');modal('Remove selected record',(c,a,d)=>{note(c,'Remove this record from the Studio project? Linked document drafts and saved practice answers remain available. Undo can restore the record.');button(a,'Remove reviewed record',()=>{changed(()=>{p[collection]=p[collection].filter(r=>r.id!==id);if(collection==='applications')for(const doc of p.documents)if(doc.applicationId===id)doc.applicationId=''});if(collection==='applications')application='';editId='';d.close();render()})})})}
